/* ============================================================
   Lain 主题音效
   ------------------------------------------------------------
   全部用 WebAudio 现场合成，不带任何音频文件：
     · 底噪  = 低通滤波的白噪声 + 55Hz 正弦（模拟 CRT / 机房嗡嗡声）
     · 悬停  = 很短的方波「嗒」
     · 点击  = 一声下滑的三角波
   浏览器/CEF 的自动播放限制：必须有一次真实交互（点击或按键）
   才能出声，所以第一次交互时才建 AudioContext。
   在「设置 → 主题 → Lain → 效果」里可以整个关掉。
   ============================================================ */
(function () {
  "use strict";

  if (window.__lainSoundLoaded) return;
  window.__lainSoundLoaded = true;

  // 开机音：Ogg Opus 转成 base64 内嵌，不依赖文件路径（主题可能装在任意目录）
  const STARTUP_B64 = "";

  // 登录 / 选择用户 / 加载用户数据 界面的音效
  const LOGIN_B64 = "";

  let ctx = null;
  let out = null;
  let master = null;
  let humStarted = false;
  let unlocked = false;
  let lastTick = 0;
  let lastHovered = null;
  let hideTimer = null;
  let humGain = null; // 底噪单独一条增益，进后台时只淡它
  let humBase = 1; // 底噪的目标电平（0=进后台，1=正常）
  let duckTimer = null;
  let activeUntil = 0; // 当前一次性音效预计播完的时间点
  let loginBuffer = null;
  let loginPlayed = false;
  let wantStartup = false;
  let wantLogin = false;
  let startupScheduled = false;

  function ensureCtx() {
    if (ctx) return ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    try {
      ctx = new AC();
    } catch (e) {
      return null;
    }
    // out 是总出口：底噪、点击音、开机音都汇到这里，静音时只动这一个节点
    out = ctx.createGain();
    out.gain.value = 1;
    out.connect(ctx.destination);

    master = ctx.createGain();
    master.gain.value = 0.12; // 整体音量，别太吵
    master.connect(out);
    return ctx;
  }

  function startHum() {
    if (!ctx || humStarted) return;
    humStarted = true;

    const seconds = 2;
    const buffer = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.5;
    }

    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    noise.loop = true;

    const lowpass = ctx.createBiquadFilter();
    lowpass.type = "lowpass";
    lowpass.frequency.value = 850;

    const noiseGain = ctx.createGain();
    noiseGain.gain.value = 0.45;

    const osc = ctx.createOscillator();
    osc.type = "sine";
    osc.frequency.value = 55;

    const oscGain = ctx.createGain();
    oscGain.gain.value = 0.1;

    noise.connect(lowpass);
    lowpass.connect(noiseGain);
    humGain = ctx.createGain();
    humGain.gain.value = 1;
    humGain.connect(master);

    noiseGain.connect(humGain);
    osc.connect(oscGain);
    oscGain.connect(humGain);

    noise.start();
    osc.start();
  }

  function blip(freq, dur, type, gain, pan) {
    if (!ctx || !master) return;
    if (ctx.state === "suspended") ctx.resume();
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const env = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    env.gain.setValueAtTime(0.0001, now);
    env.gain.exponentialRampToValueAtTime(gain, now + 0.006);
    env.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    osc.connect(env);
    if (ctx.createStereoPanner) {
      const panner = ctx.createStereoPanner();
      panner.pan.setValueAtTime(pan || 0, now);
      env.connect(panner);
      panner.connect(master);
    } else {
      env.connect(master);
    }
    osc.start(now);
    osc.stop(now + dur + 0.02);
  }

  // ---------- 开机音 ----------
  let startupBuffer = null;
  let startupPlayed = false;

  function base64ToBytes(b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }

  function loadStartup() {
    if (!ctx || startupBuffer || !STARTUP_B64 || STARTUP_B64.length < 32) return;
    try {
      const bytes = base64ToBytes(STARTUP_B64);
      ctx.decodeAudioData(
        bytes.buffer,
        function (buffer) {
          startupBuffer = buffer;
          playStartup();
        },
        function () {
          /* 解码失败就安静跳过，不影响其他音效 */
        }
      );
    } catch (e) {
      /* atob 失败等 */
    }
  }

  function playStartup() {
    if (!wantStartup) return;
    if (!ctx || !startupBuffer || startupPlayed) return;
    if (ctx.state !== "running") return; // 还没拿到自动播放许可
    startupPlayed = true;
    const src = ctx.createBufferSource();
    const gain = ctx.createGain();
    gain.gain.value = 0.55; // 开机音单独一条线，不受底噪音量影响
    src.buffer = startupBuffer;
    src.connect(gain);
    gain.connect(out);
    src.start(0);
    activeUntil = Math.max(activeUntil, ctx.currentTime + startupBuffer.duration);
    duckHum(startupBuffer.duration);
  }

  function unlock() {
    if (unlocked) return;
    unlocked = true;
    if (!ensureCtx()) return;
    if (ctx.state === "suspended") ctx.resume();
    startHum();
    loadNav();
    scheduleStartupSound();
    playStartup();
    playLogin();
  }

  // 明确的交互元素
  const EXPLICIT =
    'button, a, [role="button"], [role="option"], [role="menuitem"], [role="link"], .contextMenuItem';

  // 判断某个元素像不像「一列里的一行」（游戏侧栏、下载列表这种）
  // 依据：同一父节点下至少 3 个同名兄弟，且尺寸在行的范围内
  function isRow(el) {
    const cls = el.className;
    if (typeof cls !== "string" || !cls) return false;
    const parent = el.parentElement;
    if (!parent) return false;

    let same = 0;
    for (let i = 0; i < parent.children.length; i++) {
      if (parent.children[i].className === cls) {
        same++;
        if (same >= 3) break;
      }
    }
    if (same < 3) return false;

    const h = el.offsetHeight;
    const w = el.offsetWidth;
    return h >= 16 && h <= 140 && w >= 80;
  }

  // 从鼠标落点往上找，最多 4 层，找到「可点元素」或「一行」
  function clickableOf(target) {
    if (!target || !target.closest) return null;
    const explicit = target.closest(EXPLICIT);
    if (explicit) return explicit;

    let el = target;
    for (let i = 0; i < 4 && el && el !== document.body; i++) {
      if (isRow(el)) return el;
      el = el.parentElement;
    }
    return null;
  }

  document.addEventListener("pointerdown", unlock, true);
  document.addEventListener("keydown", unlock, true);

  document.addEventListener(
    "pointerover",
    function (e) {
      if (!unlocked || !ctx) return;
      const el = clickableOf(e.target);
      if (!el) {
        lastHovered = null;
        return;
      }
      if (el === lastHovered) return;
      lastHovered = el;
      const now = performance.now();
      if (now - lastTick < 90) return; // 划过一片按钮时不要连响
      lastTick = now;
      const pan = (e.clientX / window.innerWidth) * 1.2 - 0.6;
      blip(1600, 0.035, "square", 0.18, pan);
    },
    true
  );

  document.addEventListener(
    "pointerout",
    function (e) {
      if (lastHovered && e.target === lastHovered) lastHovered = null;
    },
    true
  );

  document.addEventListener(
    "pointerdown",
    function (e) {
      if (!unlocked) return;
      const navKey = navKeyAt(e.target);
      if (navKey) {
        playNav(navKey);
        return;
      }
      if (isFriendsButton(e.target)) {
        playNav("friends");
        return;
      }
      if (!clickableOf(e.target)) return;
      const pan = (e.clientX / window.innerWidth) * 1.2 - 0.6;
      blip(660, 0.07, "triangle", 0.22, pan);
    },
    true
  );

  // ---------- 切换界面音效（商店 / 库 / 社区 / 个人） ----------
  const NAV_B64 = {
    store: "",
    library: "",
    community: "",
    profile: "",
    friends: ""
  };

  const navBuffers = {};
  let navLoaded = false;
  let navBar = null;
  let navBarLooked = 0;

  function loadNav() {
    if (!ctx || navLoaded) return;
    navLoaded = true;
    Object.keys(NAV_B64).forEach(function (key) {
      try {
        const bytes = base64ToBytes(NAV_B64[key]);
        ctx.decodeAudioData(
          bytes.buffer,
          function (buf) {
            navBuffers[key] = buf;
          },
          function () {
            /* 解码失败跳过 */
          }
        );
      } catch (e) {}
    });
  }

  function playNav(key) {
    if (!ctx || !out) return;
    const buf = navBuffers[key];
    if (!buf) return;
    if (ctx.state === "suspended") ctx.resume();
    const src = ctx.createBufferSource();
    const gain = ctx.createGain();
    gain.gain.value = 0.5;
    src.buffer = buf;
    src.connect(gain);
    gain.connect(out);
    src.start(0);
    activeUntil = Math.max(activeUntil, ctx.currentTime + buf.duration);
    duckHum(buf.duration);
  }

  // 顶部导航条：一个容器里同时有「商店」和「社区」（英文界面则是 STORE / COMMUNITY）
  function findNavBar() {
    const nodes = document.querySelectorAll("div, button, a");
    for (let i = 0; i < nodes.length; i++) {
      const el = nodes[i];
      if (el.children.length < 3) continue;
      const r = el.getBoundingClientRect();
      if (r.height === 0 || r.height > 90 || r.top > 160) continue;
      const txt = (el.innerText || "").toUpperCase();
      if (
        (txt.indexOf("商店") >= 0 && txt.indexOf("社区") >= 0) ||
        (txt.indexOf("STORE") >= 0 && txt.indexOf("COMMUNITY") >= 0)
      ) {
        return el;
      }
    }
    return null;
  }

  // 右下角那块的小按钮（好友与聊天）。按位置认，不依赖类名和语言。
  function isFriendsButton(target) {
    let el = target;
    for (let i = 0; i < 4 && el && el !== document.body; i++) {
      const r = el.getBoundingClientRect();
      // 必须是个"小方块"：宽度受限，避免命中横跨底栏的容器
      if (r.width >= 40 && r.width <= 340 && r.height >= 18 && r.height <= 90) {
        const nearRight = window.innerWidth - r.right < 340;
        const nearBottom = window.innerHeight - r.bottom < 110;
        const inRightHalf = r.left > window.innerWidth / 2;
        if (nearRight && nearBottom && inRightHalf) {
          const t = (el.innerText || "").trim();
          if (t.length <= 24) return true;
        }
      }
      el = el.parentElement;
    }
    return false;
  }

  function navKeyAt(target) {
    if (!target || !target.closest) return null;
    if (!navBar || !navBar.isConnected) {
      const now = performance.now();
      if (now - navBarLooked < 2000) return null; // 找不到时节流，别每次点击都全文档扫
      navBarLooked = now;
      navBar = findNavBar();
      if (!navBar) return null;
    }
    if (!navBar.contains(target)) return null;

    let el = target;
    while (el && el.parentElement !== navBar) el = el.parentElement;
    if (!el) return null;

    const t = (el.innerText || "").trim().toUpperCase();
    if (t.indexOf("商店") >= 0 || t === "STORE") return "store";
    if (t.indexOf("库") >= 0 || t === "LIBRARY") return "library";
    if (t.indexOf("社区") >= 0 || t === "COMMUNITY") return "community";
    return "profile"; // 这一排里剩下的那项一般是个人主页
  }

  // ---------- 进后台 / 最小化就静音 ----------
  function setOutputMuted(muted) {
    if (!ctx || !out) return;
    const t = ctx.currentTime;
    out.gain.cancelScheduledValues(t);
    out.gain.setValueAtTime(out.gain.value, t);
    out.gain.linearRampToValueAtTime(muted ? 0 : 1, t + 0.25);
  }

  // 底噪淡入/淡出（一次性音效不受影响）
  function setHum(on) {
    humBase = on ? 1 : 0;
    if (!ctx || !humGain) return;
    const t = ctx.currentTime;
    humGain.gain.cancelScheduledValues(t);
    humGain.gain.setValueAtTime(humGain.gain.value, t);
    humGain.gain.linearRampToValueAtTime(humBase, t + 0.3);
  }

  // 播一次性音效时把底噪压到 30%，播完再慢慢抬回来
  function duckHum(durationSec) {
    if (!ctx || !humGain) return;
    const t = ctx.currentTime;
    humGain.gain.cancelScheduledValues(t);
    humGain.gain.setValueAtTime(humGain.gain.value, t);
    humGain.gain.linearRampToValueAtTime(humBase * 0.3, t + 0.08);

    clearTimeout(duckTimer);
    duckTimer = setTimeout(function () {
      if (!ctx || !humGain) return;
      const t2 = ctx.currentTime;
      humGain.gain.cancelScheduledValues(t2);
      humGain.gain.setValueAtTime(humGain.gain.value, t2);
      humGain.gain.linearRampToValueAtTime(humBase, t2 + 0.5);
    }, Math.max(300, durationSec * 1000));
  }

  // 等当前一次性音效播完再挂起，避免把话说到一半掐掉
  function suspendWhenIdle() {
    clearTimeout(hideTimer);
    const remain = ctx && ctx.state === "running" ? Math.max(0, activeUntil - ctx.currentTime) : 0;
    hideTimer = setTimeout(function () {
      if (!ctx || ctx.state !== "running") return;
      try {
        ctx.suspend();
      } catch (e) {}
    }, Math.max(400, remain * 1000 + 200));
  }

  // 进后台：只淡出底噪，正在播的切换音/开机音让它播完
  function goBackground() {
    setHum(false);
    suspendWhenIdle();
  }

  // 回到前台
  function comeForeground() {
    clearTimeout(hideTimer);
    if (!ensureCtx()) return;
    if (ctx.state === "suspended") ctx.resume();
    setOutputMuted(false);
    setHum(true);
    if (unlocked) startHum();
  }

  // 窗口被别的程序盖住时页面仍是 visible，只能靠失焦判断
  let blurTimer = null;

  window.addEventListener(
    "blur",
    function () {
      clearTimeout(blurTimer);
      blurTimer = setTimeout(function () {
        // 宽限期内如果又重新获得焦点，就当没发生
        if (document.hasFocus() && !document.hidden) return;
        goBackground();
      }, 600);
    },
    false
  );

  window.addEventListener(
    "focus",
    function () {
      clearTimeout(blurTimer);
      comeForeground();
    },
    false
  );

  document.addEventListener(
    "visibilitychange",
    function () {
      if (document.hidden) goBackground();
      else comeForeground();
    },
    false
  );

  // ---------- 登录界面音效 ----------
  function loadLogin() {
    if (!ctx || loginBuffer || !LOGIN_B64 || LOGIN_B64.length < 32) return;
    try {
      const bytes = base64ToBytes(LOGIN_B64);
      ctx.decodeAudioData(
        bytes.buffer,
        function (buffer) {
          loginBuffer = buffer;
          playLogin();
        },
        function () {
          /* 解码失败就跳过 */
        }
      );
    } catch (e) {}
  }

  function playLogin() {
    if (!wantLogin) return;
    if (!ctx || !loginBuffer || loginPlayed) return;
    if (ctx.state !== "running") return;
    loginPlayed = true;
    const src = ctx.createBufferSource();
    const gain = ctx.createGain();
    gain.gain.value = 0.5;
    src.buffer = loginBuffer;
    src.connect(gain);
    gain.connect(out);
    src.start(0);
    duckHum(loginBuffer.duration);
  }

  // 启动 400ms 后判断一次：有密码框 = 登录界面，否则当已进库
  function decideStartupSound() {
    const onLogin = !!document.querySelector('input[type="password"]');
    if (onLogin) {
      wantLogin = true;
      playLogin();
      watchForLibrary();
    } else {
      wantStartup = true;
      playStartup();
    }
  }

  // tryBoot / unlock 都可能调用，只跑一次
  function scheduleStartupSound() {
    if (startupScheduled) return;
    startupScheduled = true;
    setTimeout(decideStartupSound, 400);
  }

  // 登录界面之后，等库出现再补开机音
  function watchForLibrary() {
    let ticks = 0;
    const timer = setInterval(function () {
      ticks++;
      if (wantStartup || ticks > 180) {
        clearInterval(timer);
        return;
      }
      if (findNavBar()) {
        clearInterval(timer);
        wantStartup = true;
        playStartup();
      }
    }, 1000);
  }

  // 页面一加载就试一次；如果被自动播放策略拦住，等第一次交互再放
  (function tryBoot() {
    if (!ensureCtx()) return;
    loadStartup();
    loadNav();
    loadLogin();
    if (ctx.state === "running") startHum();
    scheduleStartupSound();
  })();
})();
